const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const passwordField=(id,label,autocomplete)=>`<div class="field"><label for="${id}">${label}</label><input id="${id}" name="${id}" type="password" minlength="8" maxlength="128" autocomplete="${autocomplete}" required><small>至少8个字符；密码只用于当前浏览器的本机登录。</small></div>`;
export function authPage(mode='login',message='',username=''){
  const register=mode==='register';
  const form=register?`<form id="registerForm"><div class="field"><label for="authUsername">用户名</label><input id="authUsername" name="username" type="text" minlength="2" maxlength="20" autocomplete="username" required><small>2—20位中文、字母、数字、下划线或短横线。</small></div>${passwordField('authPassword','设置密码','new-password')}${passwordField('authConfirmPassword','确认密码','new-password')}<button class="primary auth-submit" type="submit">创建本机账号并进入</button></form>`:`<form id="loginForm"><div class="field"><label for="authUsername">用户名</label><input id="authUsername" name="username" type="text" maxlength="20" autocomplete="username" value="${esc(username)}" required></div>${passwordField('authPassword','密码','current-password')}<button class="primary auth-submit" type="submit">登录</button></form>`;
  return `<main class="auth-shell"><section class="auth-card"><div class="auth-brand"><div class="brandicon">≈</div><div><strong>薪有数</strong><small>个人收入与个税规划</small></div></div><div class="auth-copy"><span class="eyebrow">本机账号</span><h1>${register?'创建你的访问账号':'欢迎回来'}</h1><p>${register?'设置一个只在当前浏览器生效的用户名和密码。已有工资与扣除记录会继续保留。':'登录后查看当前浏览器中保存的收入、扣除和筹划记录。'}</p></div>${message?`<div class="auth-message">${esc(message)}</div>`:''}${form}<div class="auth-local"><b>这是本机访问锁</b><p>不会创建云端账户，不支持跨设备同步。密码采用加盐校验保存，但工资数据本身未加密，仍保存在浏览器本地。当前版本不提供密码找回，请牢记密码并定期导出备份。</p></div></section><aside class="auth-side"><span>PRIVATE WORKSPACE</span><h2>你的收入记录，<br>只在你的浏览器里。</h2><ul><li>注册和登录不上传工资数据</li><li>使用后可主动退出当前会话</li><li>定期导出备份，避免浏览器清理造成丢失</li></ul></aside></main>`;
}
